<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { api } from './api'
const documents=ref<any[]>([]), results=ref<any[]>([]), evidence=ref<any[]>([]), page=ref<any>(null)
const query=ref(''), documentId=ref(''), pageNumber=ref(1), error=ref(''), notice=ref(''), busy=ref(false)
const reviewer=ref(''), note=ref(''), quote=ref(''), corrected=ref(''), kind=ref('经典原文'), printed=ref('')
async function run(fn:()=>Promise<void>) { busy.value=true; error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false} }
async function refresh(){ documents.value=(await api.request('/documents')).items;evidence.value=(await api.request('/evidence')).items }
function search(){return run(async()=>{results.value=(await api.request(`/search?q=${encodeURIComponent(query.value)}&document_id=${encodeURIComponent(documentId.value)}&limit=30`)).items})}
async function loadPage(id=documentId.value,n=pageNumber.value){ page.value=await api.request(`/documents/${encodeURIComponent(id)}/pages/${n}`);documentId.value=id;pageNumber.value=n;corrected.value=page.value.corrected_text??page.value.raw_text;kind.value=page.value.kind||'经典原文';printed.value=page.value.printed_page??'';quote.value='' }
function review(){return run(async()=>{if(!reviewer.value.trim())throw Error('请填写校核人');await api.post(`/documents/${documentId.value}/pages/${pageNumber.value}/review`,{corrected_text:corrected.value,kind:kind.value,reviewer:reviewer.value,printed_page:printed.value||null,note:note.value});await loadPage();await refresh();notice.value='页面校核已保存；原提取文本仍保留。'})}
function createEvidence(){return run(async()=>{if(!quote.value.trim()||!reviewer.value.trim())throw Error('请填写引文和校核人');await api.post('/evidence',{document_id:documentId.value,physical_page:pageNumber.value,quote:quote.value,kind:kind.value,reviewer:reviewer.value,printed_page:printed.value||null});await refresh();notice.value='证据卡已创建，临床适用性仍需规则审核。'})}
function upload(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;return run(async()=>{if(file.size>50*1024*1024)throw Error('文件超过50MiB');const data=new FormData();data.append('file',file);await api.request('/documents',{method:'POST',body:data});await refresh();notice.value='资料已登记，提取结果需逐页校核。';input.value=''})}
onMounted(()=>run(refresh))
</script>
<template><section aria-label="资料与证据"><div class="section-head"><h2>资料与证据链</h2><label class="file-button">导入 PDF（≤50MiB）<input type="file" accept="application/pdf,.pdf" @change="upload" :disabled="busy"></label></div>
<el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="notice" :title="notice" type="success" :closable="false"/>
<details class="panel"><summary>已登记资料与归属状态（{{documents.length}}份）</summary><article v-for="d in documents" :key="d.id" class="evidence-card"><strong>{{d.title}}</strong><p>物理页 {{d.physical_pages}} · 已校核 {{d.reviewed_pages}} · {{d.status}}</p><p>作者 / 注释归属：{{d.author_status || '未确认'}}</p><p class="warning">{{d.warning || '提取文字须人工核对，文件名不证明观点归属。'}}</p><small>SHA-256：{{d.sha256}}</small></article><p v-if="!documents.length" class="empty">暂无登记资料</p></details>
<div class="search-row panel"><label>检索词<input v-model="query" @keyup.enter="search" placeholder="药名、条文或关键词"></label><label>资料<select v-model="documentId"><option value="">全部资料</option><option v-for="d in documents" :key="d.id" :value="d.id">{{d.title}}（{{d.reviewed_pages}}/{{d.physical_pages}}页已核）</option></select></label><el-button type="primary" :loading="busy" @click="search">检索原文</el-button><label>物理页<input v-model.number="pageNumber" type="number" min="1"></label><el-button :disabled="!documentId || busy" @click="run(()=>loadPage())">打开页</el-button></div>
<div class="knowledge-grid"><div class="panel"><h3>检索结果 <small>{{results.length}}条 · 最多30条</small></h3><p v-if="!results.length" class="empty">暂无检索结果</p><button v-for="(item,i) in results" :key="i" class="search-result" @click="run(()=>loadPage(item.document_id,item.physical_page))"><strong>{{item.title}} · 物理页{{item.physical_page}}</strong><span class="status-text">{{item.review_status}}</span><p>{{item.snippet}}</p><small class="warning">{{item.warning}}</small></button></div>
<div class="panel" v-if="page"><div class="section-head"><h3>物理页 {{page.physical_page}} <el-tag type="warning">{{page.review_status}}</el-tag></h3><a :href="`/api/documents/${encodeURIComponent(documentId)}/pdf#page=${pageNumber}`" target="_blank" rel="noopener">回到 PDF ↗</a></div><p class="warning">{{page.warning}}</p><details open><summary>原始提取文字（未经改写）</summary><pre class="source-text">{{page.raw_text}}</pre></details><label>订正文本<textarea v-model="corrected" rows="9"></textarea></label><div class="two-fields"><label>片段类型<input v-model="kind" placeholder="如经典原文、编者注释"></label><label>印刷页码（未核留空）<input v-model="printed"></label></div><label>校核人<input v-model="reviewer"></label><label>校核说明<input v-model="note"></label><el-button type="primary" :loading="busy" @click="review">保存页面校核</el-button><hr><label>证据引文（须为已校核页有效文本子串）<textarea v-model="quote" rows="3"></textarea></label><el-button :loading="busy" @click="createEvidence">建立证据卡</el-button></div><div class="panel empty" v-else>选择检索结果或指定物理页，核对原件后再建证据卡。</div></div>
<div class="panel"><h3>证据卡 <small>{{evidence.length}}条</small></h3><div class="evidence-list"><article v-for="e in evidence" :key="e.id" class="evidence-card"><el-tag>资料证据 · {{e.kind}}</el-tag><blockquote>{{e.quote}}</blockquote><small>{{e.id}} · 物理页{{e.physical_page}} · {{e.reviewer}}</small><button class="text-link" @click="run(()=>loadPage(e.document_id,e.physical_page))">查看来源页</button></article><p v-if="!evidence.length" class="empty">尚未创建证据卡</p></div></div>
</section></template>
